package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

/**
 * Unit tests for ReferenceType#getGenericSignature
 */
public class ReferenceType_getGenericSignature_TriageGen1Test {

    @Test
    public void testGetGenericSignature_Success() {
        // Arrange
        // We need to mock the behavior of the internal _referencedType field.
        // Since _referencedType is likely a private field, we use the static factory 
        // or construct a mock of ReferenceType and use reflection if necessary.
        // However, based on the provided signature, we can use Mockito to mock the 
        // dependencies and the behavior of the referenced type.

        JavaType mockReferencedType = Mockito.mock(JavaType.class);

        // ReferenceType is a class we are testing, so we create a real instance.
        // Since the constructor is protected, we use the construct method.
        // We need to provide a real or mocked class and JavaType.
        ReferenceType referenceType = ReferenceType.construct(
                String.class, 
                mockReferencedType, 
                null, 
                null
        );

        // We need to ensure the internal _referencedType of our 'referenceType' instance 
        // returns our 'mockReferencedType'. 
        // In Jackson's ReferenceType, _referencedType is usually set via constructor.
        // Because we cannot easily inject into a private field without reflection, 
        // we rely on the fact that the construct method uses the refType provided.

        // Mocking the behavior of the referenced type's getGenericSignature method
        when(mockReferencedType.getGenericSignature(any(StringBuilder.class))).thenAnswer(invocation -> {
            StringBuilder sb = invocation.getArgument(0);
            sb.append("MockedType");
            return sb;
        });

        StringBuilder sb = new StringBuilder("Start");

        // Act
        StringBuilder result = referenceType.getGenericSignature(sb);

        // Assert
        // Expected pattern: < + [result of referencedType] + >;
        // Input "Start" -> "<" + "MockedType" + ">;" -> "Start<MockedType>;"
        assertEquals("Start<MockedType>;", result.toString());
    }

    @Test
    public void testGetGenericSignature_EmptyStringBuilder() {
        // Arrange
        JavaType mockReferencedType = Mockito.mock(JavaType.class);
        ReferenceType referenceType = ReferenceType.construct(
                Object.class, 
                mockReferencedType, 
                null, 
                null
        );

        when(mockReferencedType.getGenericSignature(any(StringBuilder.class))).thenAnswer(invocation -> {
            StringBuilder sb = invocation.getArgument(0);
            sb.append("Inner");
            return sb;
        });

        StringBuilder sb = new StringBuilder();

        // Act
        StringBuilder result = referenceType.getGenericSignature(sb);

        // Assert
        assertEquals("<Inner>;", result.toString());
    }

    @Test
    public void testGetGenericSignature_NullStringBuilder_ThrowsException() {
        // Arrange
        JavaType mockReferencedType = Mockito.mock(JavaType.class);
        ReferenceType referenceType = ReferenceType.construct(
                Object.class, 
                mockReferencedType, 
                null, 
                null
        );

        // Act & Assert
        try {
            referenceType.getGenericSignature(null);
        } catch (NullPointerException e) {
            // Success
        }
    }
}
